package com.example

/**
 * Grade 10 Science Syllabus Question Bank for Live Exam Hall.
 * Covers Terms 1, 2, and 3 with 60 distinct syllabus topic slots per term.
 * Each slot provides 30 distinct variants corresponding to papers 1 to 30.
 */
object ScienceGrade10QuestionBank {

  fun getQuestion(term: Int, paperIdx: Int, qNum: Int): MockExamQuestion {
    val cleanPaper = if (paperIdx in 1..30) paperIdx else 1
    val cleanQ = if (qNum in 1..60) qNum else 1
    val effectiveSlot = ((cleanQ - 1 + (cleanPaper - 1) * 7) % 60) + 1
    return when (term) {
      1 -> getTerm1Question(cleanPaper, cleanQ, effectiveSlot)
      2 -> getTerm2Question(cleanPaper, cleanQ, effectiveSlot)
      else -> getTerm3Question(cleanPaper, cleanQ, effectiveSlot)
    }
  }

  // ==========================================================================
  // GRADE 10 - TERM 1 (Slots 1 to 60)
  // ==========================================================================
  private fun getTerm1Question(paperIdx: Int, qNum: Int, slot: Int): MockExamQuestion {
    val v = paperIdx - 1
    val (topic, quad) = when (slot) {
      1 -> "ජීවයේ රසායනික පදනම - ජෛව අණු" to run {
        val bioMols = listOf(
          Triple("කාබෝහයිඩ්‍රේටවල මූලික තැනුම් ඒකකය වන්නේ කුමක්ද?", listOf("ග්ලූකෝස් (මොනොසැකරයිඩ)", "ඇමයිනෝ අම්ල", "මේද අම්ල හා ග්ලිසරෝල්", "නියුක්ලියෝටයිඩ"), 1 to "කාබෝහයිඩ්‍රේටවල මූලික තැනුම් ඒකකය මොනොසැකරයිඩ (ග්ලූකෝස්) වේ."),
          Triple("ප්‍රෝටීන අණුවල මූලික ව්‍යුහාත්මක තැනුම් ඒකකය වන්නේ කුමක්ද?", listOf("ඇමයිනෝ අම්ල", "ග්ලූකෝස්", "මේද අම්ල", "නියුක්ලියෝටයිඩ"), 1 to "ඇමයිනෝ අම්ල පෙප්ටයිඩ බන්ධන මඟින් බැඳී ප්‍රෝටීන සාදයි."),
          Triple("ලිපිඩ අණුවක් සෑදීමට දායක වන ප්‍රධාන සංඝටක වන්නේ,", listOf("මේද අම්ල සහ ග්ලිසරෝල්", "ග්ලූකෝස් සහ ෆ්‍රක්ටෝස්", "ඇමයිනෝ අම්ල", "නියුක්ලියෝටයිඩ"), 1 to "ග්ලිසරෝල් අණුවක් සමඟ මේද අම්ල අණු 3ක් එස්ටර බන්ධන මඟින් බැඳී ලිපිඩ සාදයි."),
          Triple("න්‍යෂ්ටික අම්ලවල (DNA හා RNA) මූලික තැනුම් ඒකකය කුමක්ද?", listOf("නියුක්ලියෝටයිඩය", "ඇමයිනෝ අම්ලය", "පොලිපෙප්ටයිඩය", "මොනොසැකරයිඩය"), 1 to "නියුක්ලියෝටයිඩයක් පෙන්ටෝස් සීනි, පොස්පේට් හා නයිට්‍රජනීය භෂ්මයකින් සමන්විත වේ.")
        )
        val item = bioMols[v % bioMols.size]
        Quad(item.first, item.second, item.third.first, item.third.second)
      }
      2 -> "ජීවයේ රසායනික පදනම - ආහාර පරීක්ෂණ" to run {
        val tests = listOf(
          Triple("ග්ලූකෝස් හඳුනාගැනීම සඳහා බෙනඩික්ට් ද්‍රාවණය සමඟ රත් කළ විට ලැබෙන නිරීක්ෂණය කුමක්ද?", listOf("ගඩොල් රතු අවක්ෂේපය", "තද නිල් පැහැය", "දම් පැහැය", "කළු අවක්ෂේපය"), 1 to "බෙනඩික්ට් පරීක්ෂාවේදී ඔක්සිහාරක සීනි නිසා Cu₂O ගඩොල් රතු අවක්ෂේපය ලැබේ."),
          Triple("පිෂ්ඨය හඳුනාගැනීම සඳහා යොදන අයඩින් පරීක්ෂාවේදී ලැබෙන සුවිශේෂී නිරීක්ෂණය කුමක්ද?", listOf("තද නිල්-කළු පැහැය", "ගඩොල් රතු අවක්ෂේපය", "දම් පැහැය", "රෝස පැහැය"), 1 to "අයඩින් ද්‍රාවණය පිෂ්ඨය සමඟ තද නිල්-කළු සංකීර්ණයක් සාදයි."),
          Triple("ප්‍රෝටීන හඳුනාගැනීමේ බයියුරෙට් පරීක්ෂාවේදී ලැබෙන වර්ණ විපර්යාසය කුමක්ද?", listOf("දම් (රෝස-දම්) පැහැය", "ගඩොල් රතු පැහැය", "කහ පැහැය", "කොළ පැහැය"), 1 to "ක්ෂාරීය මාධ්‍යයේ Cu²⁺ අයන පෙප්ටයිඩ බන්ධන සමඟ දම් පැහැය ලබාදෙයි."),
          Triple("ලිපිඩ හඳුනාගැනීමට සුඩාන් III ප්‍රතිකාරකය එක් කළ විට ලැබෙන නිරීක්ෂණය කුමක්ද?", listOf("දීප්තිමත් රතු වළල්ල හෝ බිඳිති", "තද නිල් පැහැය", "දම් පැහැය", "සුදු අවක්ෂේපය"), 1 to "සුඩාන් III මේද-ද්‍රාව්‍ය ඩයි වර්ගයක් බැවින් ලිපිඩ තට්ටුව රතු පැහැ ගන්වයි.")
        )
        val item = tests[v % tests.size]
        Quad(item.first, item.second, item.third.first, item.third.second)
      }
      3 -> "ජීවයේ රසායනික පදනම - විටමින් හා ඌනතා" to run {
        val vits = listOf(
          Triple("විටමින් A ඌනතාවය නිසා ඇස ආශ්‍රිතව ඇතිවන ප්‍රධාන රෝගී තත්ත්වය කුමක්ද?", listOf("රාත්‍රී අන්ධතාවය (Night blindness)", "ස්කර්වි", "රිකට්සියාව", "ඇනීමියාව"), 1 to "දෘෂ්ටිවිතානයේ රොඩොප්සින් නිපදවීමට විටමින් A අත්‍යවශ්‍ය වේ."),
          Triple("විටමින් C ඌනතාවය නිසා විදුරුමහෙන් ලේ ගැලීම සිදුවන රෝගය කුමක්ද?", listOf("ස්කර්වි (Scurvy)", "බෙරිබෙරි", "රාත්‍රී අන්ධතාව", "රිකට්සියාව"), 1 to "කොලැජන් සංස්ලේෂණයට විටමින් C අත්‍යවශ්‍ය වන අතර ඌනතාවයෙන් ස්කර්වි වැළඳේ."),
          Triple("විටමින් D ඌනතාවය හේතුවෙන් කුඩා දරුවන්ගේ අස්ථි දුර්වල වී ඇතිවන රෝගය කුමක්ද?", listOf("රිකට්සියාව (Rickets)", "ස්කර්වි", "පැපොල", "ගලගණ්ඩය"), 1 to "විටමින් D කැල්සියම් අවශෝෂණයට උපකාරී වන අතර ඌනතාවයෙන් අස්ථි නැමී රිකට්සියාව සාදයි."),
          Triple("ශරීරයේ හිමොග්ලොබින් නිපදවීමට අත්‍යවශ්‍ය යකඩ (Fe) ඌන වූ විට වැළඳෙන රෝගය කුමක්ද?", listOf("නීරක්තිය (ඇනීමියාව)", "ගලගණ්ඩය", "ස්කර්වි", "දියවැඩියාව"), 1 to "යකඩ ඌනතාවයෙන් හිමොග්ලොබින් මට්ටම පහත වැටී නීරක්තිය ඇතිවේ.")
        )
        val item = vits[v % vits.size]
        Quad(item.first, item.second, item.third.first, item.third.second)
      }
      4 -> "ජීවයේ රසායනික පදනම - ජලයේ ගුණ" to run {
        val waterProps = listOf(
          Triple("ජලයේ ඉහළ විශිෂ්ට තාප ධාරිතාව නිසා ජීවී දේහයට ලැබෙන ප්‍රධාන වාසිය කුමක්ද?", listOf("දේහ උෂ්ණත්වය නියතව පවත්වා ගැනීමට පහසු වීම", "දේහය ක්ෂණිකව රත්වීම", "ජලය ඉක්මනින් මිදීම", "දේහ බර අඩුවීම"), 1 to "ඉහළ විශිෂ්ට තාප ධාරිතාව නිසා ජලය තාප බෆරයක් ලෙස ක්‍රියා කර උෂ්ණත්වය පාලනය කරයි."),
          Triple("ශාක තුළ ජල කඳ අඛණ්ඩව ඉහළට ඇදී යාමට ජල අණු එකිනෙක බැඳ තබන බලය කුමක්ද?", listOf("සංසක්ති බල (Cohesion)", "ආසක්ති බල පමණි", "ගුරුත්වාකර්ෂණ බල", "ස්ථිති විද්‍යුත් බල"), 1 to "හයිඩ්‍රජන් බන්ධන නිසා ජල අණු අතර ඇතිවන ආකර්ෂණය සංසක්ති බලයයි."),
          Triple("ජලය 4 °C දී උපරිම ඝනත්වයක් දැක්වීම නිසා ශීත රටවල ජලාශවල සිදුවන්නේ කුමක්ද?", listOf("අයිස් මතුපිට පාවෙමින් යටි ජලය ද්‍රවව පැවතී ජලජ ජීවීන් සුරැකීම", "මුළු ජලාශයම එකවර මිදීම", "යටි ජලය මිදී මසුන් මියයාම", "ජලයේ ඔක්සිජන් ඉවත්වීම"), 1 to "අයිස් ඝනත්වය අඩු බැවින් මතුපිට පාවී පරිවාරකයක් සේ ක්‍රියා කරයි."),
          Triple("ජල අණුවක් තුළ හයිඩ්‍රජන් හා ඔක්සිජන් අතර පවතින රසායනික බන්ධන ස්වභාවය කුමක්ද?", listOf("ධ්‍රැවීය සහසංයුජ බන්ධන", "අයනික බන්ධන", "ලෝහක බන්ධන", "ද්විත්ව බන්ධන"), 1 to "ඔක්සිජන්හි ඉහළ විද්‍යුත් සෘණතාව නිසා ඉලෙක්ට්‍රෝන යුගලය අසමානව බෙදී ධ්‍රැවීය වේ.")
        )
        val item = waterProps[v % waterProps.size]
        Quad(item.first, item.second, item.third.first, item.third.second)
      }
      5 -> "ජීවයේ රසායනික පදනම - ඛනිජ ලවණ" to run {
        val minerals = listOf(
          Triple("තයිරොයිඩ් ග්‍රන්ථියෙන් තයිරොක්සින් හෝමෝනය නිපදවීමට අත්‍යවශ්‍ය වන ඛනිජය කුමක්ද?", listOf("අයඩින් (I)", "යකඩ (Fe)", "කැල්සියම් (Ca)", "සෝඩියම් (Na)"), 1 to "අයඩින් ඌනතාවය නිසා තයිරොයිඩ් ග්‍රන්ථිය ඉදිමී ගලගණ්ඩය ඇතිවේ."),
          Triple("අස්ථි සහ දත් ශක්තිමත්ව තබා ගැනීමට සහ රුධිරය කැටිගැසීමට අවශ්‍ය ඛනිජය කුමක්ද?", listOf("කැල්සියම් (Ca)", "යකඩ (Fe)", "අයඩින් (I)", "පොටෑසියම් (K)"), 1 to "අස්ථිවල ප්‍රධාන ඛනිජය කැල්සියම් වන අතර රුධිර කැටිගැසීමේ ක්‍රියාවලියටද අවශ්‍ය වේ."),
          Triple("ශාකවල හරිතප්‍රද (Chlorophyll) අණුවේ කේන්ද්‍රීය පරමාණුව ලෙස පවතින ඛනිජය කුමක්ද?", listOf("මැග්නීසියම් (Mg)", "යකඩ (Fe)", "සල්ෆර් (S)", "සෝඩියම් (Na)"), 1 to "හරිතප්‍රද අණුවේ කේන්ද්‍රයේ මැග්නීසියම් (Mg) පරමාණුවක් පිහිටයි."),
          Triple("ස්නායු ආවේග සම්ප්‍රේෂණයට සහ දේහ තරලවල ඔස්මොටික පීඩනය පාලනයට අත්‍යවශ්‍ය අයනය කුමක්ද?", listOf("සෝඩියම් (Na⁺)", "යකඩ (Fe²⁺)", "අයඩින් (I⁻)", "තඹ (Cu²⁺)"), 1 to "Na⁺ සහ K⁺ අයන ස්නායු ආවේග ගමන් කිරීමට හා ඔස්මෝ තුල්‍යතාවට දායක වේ.")
        )
        val item = minerals[v % minerals.size]
        Quad(item.first, item.second, item.third.first, item.third.second)
      }
      6 -> "ජීවයේ රසායනික පදනම - න්‍යෂ්ටික අම්ල" to run {
        val naList = listOf(
          Triple("DNA අණුවක ඇති නයිට්‍රජනීය භෂ්ම 4 අතරින් ඇඩිනින් (A) සමඟ යුගලනය වන්නේ කුමක්ද?", listOf("තයිමින් (T)", "ගුවනින් (G)", "සයිටොසින් (C)", "යුරැසිල් (U)"), 1 to "පරිපූරක භෂ්ම යුගලනය: A සමඟ T හයිඩ්‍රජන් බන්ධන 2කින්ද, G සමඟ C බන්ධන 3කින්ද බැඳේ."),
          Triple("RNA අණුවක පමණක් අඩංගු වන අතර DNA හි නොමැති නයිට්‍රජනීය භෂ්මය කුමක්ද?", listOf("යුරැසිල් (U)", "තයිමින් (T)", "ඇඩිනින් (A)", "ගුවනින් (G)"), 1 to "RNA හි තයිමින් (T) වෙනුවට යුරැසිල් (U) අඩංගු වේ."),
          Triple("ජීවීන්ගේ ප්‍රවේණික තොරතුරු පරම්පරාවෙන් පරම්පරාවට ගෙන යන ද්විත්ව හෙලික්සීය අණුව කුමක්ද?", listOf("DNA (ඩියොක්සිරයිබෝස් න්‍යෂ්ටික අම්ලය)", "ග්ලයිකොජන්", "හිමොග්ලොබින්", "ඉන්සියුලින්"), 1 to "DNA අණුවේ නියුක්ලියෝටයිඩ අනුපිළිවෙල ප්‍රවේණික කේතය ලෙස ක්‍රියා කරයි."),
          Triple("සෛලයේ ප්‍රෝටීන සංස්ලේෂණයට සෘජුවම දායක වන තනි දාමමය න්‍යෂ්ටික අම්ලය කුමක්ද?", listOf("RNA (රයිබෝස් න්‍යෂ්ටික අම්ලය)", "DNA", "ග්ලූකෝස්", "ATP"), 1 to "mRNA, tRNA සහ rRNA ප්‍රෝටීන නිපදවීමේ ක්‍රියාවලියට දායක වේ.")
        )
        val item = naList[v % naList.size]
        Quad(item.first, item.second, item.third.first, item.third.second)
      }
      7 -> "පදාර්ථයේ ව්‍යුහය - උප පරමාණුක අංශු" to run {
        val particles = listOf(
          Triple("පරමාණුවක න්‍යෂ්ටිය තුළ අඩංගු වන උප පරමාණුක අංශු මොනවාද?", listOf("ප්‍රෝටෝන සහ නියුට්‍රෝන", "ඉලෙක්ට්‍රෝන සහ ප්‍රෝටෝන", "ඉලෙක්ට්‍රෝන පමණි", "නියුට්‍රෝන පමණි"), 1 to "න්‍යෂ්ටිය ප්‍රෝටෝන (+) සහ ආරෝපණ රහිත නියුට්‍රෝන (0) වලින් සමන්විත වේ."),
          Triple("පරමාණුවක න්‍යෂ්ටිය වටා කවචවල භ්‍රමණය වන සෘණ ආරෝපිත අංශු මොනවාද?", listOf("ඉලෙක්ට්‍රෝන", "ප්‍රෝටෝන", "නියුට්‍රෝන", "ඇල්ෆා අංශු"), 1 to "ඉලෙක්ට්‍රෝන සෘණ (-1) ආරෝපණයක් දරන අතර ශක්ති මට්ටම්වල පවතී."),
          Triple("උදාසීන පරමාණුවක අනිවාර්යයෙන්ම එකිනෙකට සමාන වන අංශු සංඛ්‍යාව කුමක්ද?", listOf("ප්‍රෝටෝන සංඛ්‍යාව සහ ඉලෙක්ට්‍රෝන සංඛ්‍යාව", "ප්‍රෝටෝන සහ නියුට්‍රෝන", "නියුට්‍රෝන සහ ඉලෙක්ට්‍රෝන", "කිසිවක් සමාන නොවේ"), 1 to "උදාසීන පරමාණුවක ධන ප්‍රෝටෝන ගණන සෘණ ඉලෙක්ට්‍රෝන ගණනට සමාන බැවින් ශුද්ධ ආරෝපණය බිංදුවයි."),
          Triple("පරමාණුවක ස්කන්ධයෙන් 99.9% කට වඩා සංකේන්ද්‍රණය වී ඇත්තේ කොහේද?", listOf("න්‍යෂ්ටිය තුළ", "ඉලෙක්ට්‍රෝන කවචවල", "පිටතම කවචයේ", "හිස් අවකාශයේ"), 1 to "ප්‍රෝටෝන හා නියුට්‍රෝනවල ස්කන්ධය ඉලෙක්ට්‍රෝනයට වඩා ~1840 ගුණයකින් වැඩි බැවින් ස්කන්ධය න්‍යෂ්ටියේ ඇත.")
