          Triple("හයිඩ්‍රජන්හි ස්වභාවික සමස්ථානික 3 අතරින් නියුට්‍රෝන නොමැති සමස්ථානිකය කුමක්ද?", listOf("ප්‍රෝටියම් (¹H)", "ඩියුටීරියම් (²H)", "ට්‍රිටියම් (³H)", "කිසිවක් නොවේ"), 1 to "ප්‍රෝටියම් (¹H) හි න්‍යෂ්ටියේ ඇත්තේ ප්‍රෝටෝනයක් පමණි, නියුට්‍රෝන නැත."),
          Triple("කාබනික ද්‍රව්‍යවල කාල නිර්ණය සඳහා (Carbon Dating) යොදාගන්නා විකිරණශීලී සමස්ථානිකය කුමක්ද?", listOf("කාබන්-14 (¹⁴C)", "කාබන්-12 (¹²C)", "කාබන්-13 (¹³C)", "යූරේනියම්-238"), 1 to "කාබන්-14 හි අර්ධ ආයු කාලය අවුරුදු 5730ක් වන අතර පුරාවිද්‍යා කාල නිර්ණයට යොදාගනී."),
          Triple("තයිරොයිඩ් ග්‍රන්ථියේ පිළිකා ප්‍රතිකාර සඳහා යොදාගන්නා විකිරණශීලී සමස්ථානිකය කුමක්ද?", listOf("අයඩින්-131 (¹³¹I)", "කොබෝල්ට්-60", "කාබන්-14", "සෝඩියම්-24"), 1 to "තයිරොයිඩ් පටක මඟින් අයඩින් උරාගන්නා බැවින් I-131 විකිරණ ප්‍රතිකාරයට භාවිත වේ.")
        )
        val item = isotopes[v % isotopes.size]
        Quad(item.first, item.second, item.third.first, item.third.second)
      }
      else -> {
        // Build dynamic syllabus-based question for slot 11..60
        getTerm1DynamicSlot(slot, v)
      }
    }

    return MockExamQuestion(
      id = qNum,
      questionText = "ආදර්ශ පත්‍රය ${String.format("%02d", paperIdx)} • ප්‍රශ්නය $qNum: ${quad.q}",
      options = quad.opts,
      correctOption = quad.c,
      explanation = quad.exp,
      topicName = topic
    )
  }

  private fun getTerm1DynamicSlot(slot: Int, v: Int): Pair<String, Quad> {
    return when (slot) {
      in 11..16 -> "සෛලීය ව්‍යුහය හා ඉන්ද්‍රයිකා" to run {
        val cellQuestions = listOf(
          Quad("සෛලීය ශ්වසනය මඟින් ATP ලෙස ශක්තිය නිපදවන සෛලයේ ශක්ති බලාගාරය කුමක්ද?", listOf("මයිටොකොන්ඩ්‍රියම", "හරිතලවය", "ගොල්ගි දේහය", "රයිබොසෝමය"), 1, "මයිටොකොන්ඩ්‍රියාවල කෲස්ටේ මත සෛලීය ශ්වසනයෙන් ATP නිපදවේ."),
          Quad("ශාක සෛලවල ප්‍රභාසංස්ලේෂණය සිදුකරන ප්‍රභාසංස්ලේෂක වර්ණක දරන ඉන්ද්‍රයිකාව කුමක්ද?", listOf("හරිතලවය (Chloroplast)", "මයිටොකොන්ඩ්‍රියම", "රයිබොසෝමය", "කේන්ද්‍රදේහය"), 1, "හරිතලව තුළ තයිලකොයිඩ හා ස්ට්‍රෝමාව පවතින අතර ප්‍රභාසංස්ලේෂණය සිදුකරයි."),
          Quad("සෛලයේ ප්‍රෝටීන සංස්ලේෂණය සිදුකරන ප්‍රධාන ඉන්ද්‍රයිකාව වන්නේ කුමක්ද?", listOf("රයිබොසෝමය (Ribosome)", "ලයිසොසෝමය", "මධ්‍ය රික්තකය", "කේන්ද්‍රදේහය"), 1, "රයිබොසෝම mRNA අච්චුව අනුව ඇමයිනෝ අම්ල එකලස් කරමින් ප්‍රෝටීන තනයි."),
          Quad("ශාක සෛලයක සෙලියුලෝස් වලින් සමන්විත පිටතම දෘඪ ආවරණය කුමක්ද?", listOf("සෛල බිත්තිය", "ප්ලාස්ම පටලය", "ටොනොප්ලාස්ටය", "න්‍යෂ්ටිකාව"), 1, "සෛල බිත්තිය සෙලියුලෝස් වලින් සෑදී ශාක සෛලයට යාන්ත්‍රික ආධාරකය සපයයි."),
          Quad("සෛලයට ඇතුළු වන හා පිටවන ද්‍රව්‍ය පාලනය කරන අර්ධ පාරගම්‍ය පටලය කුමක්ද?", listOf("ප්ලාස්ම පටලය", "සෛල බිත්තිය", "න්‍යෂ්ටිකාව", "එන්ඩොප්ලාස්මීය ජාලිකාව"), 1, "ප්ලාස්ම පටලය ෆොස්ෆොලිපිඩ ද්විත්ව ස්ථරයකින් යුක්ත වන අතර වරණීය පාරගම්‍ය වේ."),
          Quad("සෛල විභාජනයේදී තර්කුව සෑදීමට උපකාරී වන සත්ත්ව සෛලවල පමණක් ඇති ඉන්ද්‍රයිකාව කුමක්ද?", listOf("කේන්ද්‍රදේහය (Centrosome)", "හරිතලවය", "සෛල බිත්තිය", "විශාල මධ්‍ය රික්තකය"), 1, "කේන්ද්‍රදේහය සත්ත්ව සෛල විභාජනයේදී තර්කු තන්තු සංවිධානය කරයි.")
        )
        cellQuestions[(slot - 11 + v).mod(cellQuestions.size)]
      }
      in 17..22 -> "සෛල විභාජනය" to run {
        val divQuestions = listOf(
          Quad("දේහ සෛල වර්ධනයට හා පටක අලුත්වැඩියාවට දායක වන වර්ණදේහ සංඛ්‍යාව නොවෙනස්ව පවතින විභාජනය කුමක්ද?", listOf("අනුනන විභාජනය (Mitosis)", "ඌනන විභාජනය", "ද්විඛණ්ඩනය", "අංකුරණය"), 1, "අනුනනයේදී 2n මාතෘ සෛලයකින් සමාන 2n දුහිතෘ සෛල 2ක් සෑදේ."),
          Quad("ලිංගික ප්‍රජනනය සඳහා ජන්මාණු සෑදීමේදී වර්ණදේහ සංඛ්‍යාව අඩක් (n) කරන විභාජනය කුමක්ද?", listOf("ඌනන විභාජනය (Meiosis)", "අනුනන විභාජනය", "ද්විඛණ්ඩනය", "පුනර්වර්ධනය"), 1, "ඌනන විභාජනයේදී 2n සෛලයකින් ඒකගුණ (n) ජන්මාණු සෛල 4ක් ලැබේ."),
          Quad("අනුනන විභාජනයේදී වර්ණදේහ සෛලයේ මධ්‍ය රේඛාවේ (සමක තලයේ) පෙළගැසෙන අවස්ථාව කුමක්ද?", listOf("මැද අවස්ථාව (Metaphase)", "පෙර අවස්ථාව", "පසු අවස්ථාව", "අන්ත අවස්ථාව"), 1, "මෙටාෆේස් අවස්ථාවේදී වර්ණදේහ කේන්ද්‍රිකාවලින් තර්කු තන්තු සමඟ බැඳී සමක තලයේ පෙළගැසේ."),
