  // ==========================================================================
  // GRADE 10 - TERM 2 (Slots 1 to 60)
  // ==========================================================================
  private fun getTerm2Question(paperIdx: Int, qNum: Int, slot: Int): MockExamQuestion {
    val v = paperIdx - 1
    val (topic, quad) = when (slot) {
      in 1..8 -> "ශාක සහ සත්ත්ව පටක" to run {
        val tissueList = listOf(
          Quad("ශාකවල ප්‍රභාසංස්ලේෂණය, ආහාර ගබඩා කිරීම හා සෛල පිම්බුම පවත්වා ගන්නා සරල පටකය කුමක්ද?", listOf("මෘදුස්තර පටකය (Parenchyma)", "දෘඪස්තර පටකය", "ශෛලම පටකය", "ප්ලෝයම පටකය"), 1, "මෘදුස්තර සෛල ජීවී වන අතර තුනී සෙලියුලෝස් බිත්ති සහිතව ආහාර ගබඩා කරයි."),
