          Quad("නිදහසේ පහළට වැටෙන වස්තුවක මුළු යාන්ත්‍රික ශක්තිය (විභව ශක්තිය + චාලක ශක්තිය) සම්බන්ධයෙන් සත්‍ය ප්‍රකාශය කුමක්ද?", listOf("වායු ප්‍රතිරෝධය නොසලකා හැරිය විට මුළු යාන්ත්‍රික ශක්තිය නියතව පවතී", "පහළට වැටෙන විට මුළු ශක්තිය අඩුවේ", "පහළට වැටෙන විට විභව ශක්තිය වැඩිවේ", "මුළු ශක්තිය ශුන්‍ය වේ"), 1, "යාන්ත්‍රික ශක්ති සංස්ථිති නියමයට අනුව විභව ශක්තිය චාලක ශක්තිය බවට පරිවර්තනය වෙමින් එකතුව නියත වේ."),
          Quad("ජාත්‍යන්තර සම්මත ක්‍රමයට අනුව ක්ෂමතාව මනින SI ඒකකය කුමක්ද?", listOf("වොට් (W හෝ J s⁻¹)", "ජූල් (J)", "නිව්ටන් (N)", "පැස්කල් (Pa)"), 1, "තත්පරයකදී ජූල් 1 ක කාර්යයක් කිරීමේ සීඝ්‍රතාව වොට් 1 කි (1 W = 1 J s⁻¹)."),
          Quad("කාර්යය හා ශක්තිය මනින සම්මත SI ඒකකය වන්නේ කුමක්ද?", listOf("ජූල් (J)", "වොට් (W)", "නිව්ටන් (N)", "කැලරි (cal)"), 1, "කාර්යය හා සියලු ආකාරයේ ශක්ති මනින සම්මත ඒකකය ජූල් (J) වේ.")
        )
        pList[(slot - 49 + v).mod(pList.size)]
      }
      else -> "පීඩනය සහ ද්‍රවස්ථිති පීඩනය" to run {
        val pressList = listOf(
          Quad("වර්ගඵලය 2 m² වූ පෘෂ්ඨයක් මත 100 N ලම්භක බලයක් යෙදූ විට ඇතිවන පීඩනය (P = F / A) කොපමණද?", listOf("50 Pa (හෝ N m⁻²)", "200 Pa", "100 Pa", "25 Pa"), 1, "පීඩනය (P) = බලය (F) / වර්ගඵලය (A) = 100 N / 2 m² = 50 N m⁻² (Pa) වේ."),
          Quad("නිශ්චල ද්‍රවයක h ගැඹුරකදී ද්‍රව පීඩනය රඳා පවතින සාධක නිවැරදිව දක්වා ඇති සූත්‍රය කුමක්ද?", listOf("P = h ρ g", "P = F / A", "P = m g h", "P = ½ ρ v²"), 1, "ද්‍රව පීඩනය ගැඹුර (h), ද්‍රවයේ ඝනත්වය (ρ) සහ ගුරුත්වජ ත්වරණය (g) මත රඳා පවතී."),
          Quad("එකම ගැඹුරකදී ජලයට (ඝනත්වය = 1000 kg m⁻³) වඩා රසදිය (ඝනත්වය = 13600 kg m⁻³) තුළ ඇතිවන පීඩනය කුමක්ද?", listOf("රසදිය තුළ පීඩනය 13.6 ගුණයකින් වැඩිය", "ජලය තුළ පීඩනය වැඩිය", "දෙකෙහිම පීඩනය සමාන වේ", "රසදිය තුළ පීඩනයක් නැත"), 1, "P = hρg බැවින් ඝනත්වය (ρ) වැඩිවත්ම ද්‍රව පීඩනය සමානුපාතිකව වැඩිවේ."),
          Quad("මුහුදු මට්ටමේදී සම්මත වායුගෝලීය පීඩනය රසදිය මිලිමීටර කොපමණකින් නිරූපණය වේද?", listOf("760 mmHg (හෝ 76 cmHg)", "100 mmHg", "500 mmHg", "1000 mmHg"), 1, "සම්මත වායුගෝලීය පීඩනය 760 mmHg වන අතර එය ආසන්න වශයෙන් 101,325 Pa (101 kPa) වේ."),
          Quad("බහාලුමක අඩංගු සංවෘත ද්‍රවයක් මත යොදන පීඩනය සියලු දිශාවලට අඩු වීමකින් තොරව සම්ප්‍රේෂණය වන බව ප්‍රකාශ කළ නියමය කුමක්ද?", listOf("පැස්කල්ගේ නියමය (Pascal's Principle)", "ආකිමිඩීස් නියමය", "බෝයිල් නියමය", "චාල්ස් නියමය"), 1, "හයිඩ්‍රොලික් තිරිංග සහ ජැක් ක්‍රියා කරන්නේ පැස්කල් නියමය පදනම් කරගෙනය."),
          Quad("වායුගෝලීය පීඩනය මැනීම සඳහා ප්‍රායෝගිකව භාවිත කරන විද්‍යාත්මක උපකරණය කුමක්ද?", listOf("රසදිය බැරෝමීටරය", "මනෝමීටරය", "තර්මෝමීටරය", "ඇමීටරය"), 1, "ටොරිසෙලි විසින් නිපදවූ සරල රසදිය බැරෝමීටරය වායුගෝලීය පීඩනය මනියි.")
        )
        pressList[(slot - 55 + v).mod(pressList.size)]
      }
    }

    return MockExamQuestion(
      id = qNum,
      questionText = "ආදර්ශ පත්‍රය ${String.format("%02d", paperIdx)} • ප්‍රශ්නය $qNum: ${quad.q}",
      options = quad.opts,
      correctOption = quad.c,
      explanation = quad.exp,
      topicName = topic
    )
  }

  // ==========================================================================
  // GRADE 10 - TERM 3 (Slots 1 to 60)
  // ==========================================================================
  private fun getTerm3Question(paperIdx: Int, qNum: Int, slot: Int): MockExamQuestion {
    val v = paperIdx - 1
    val (topic, quad) = when (slot) {
      in 1..8 -> "ධාරා විද්‍යුතය සහ ඕම් නියමය" to run {
        val r = 2 + (v % 5) * 2
        val i = 2 + ((slot - 1).mod(3))
        val volt = r * i
        Quad(
          "ප්‍රතිරෝධය $r Ω වූ සන්නායක කම්බියක් හරහා $i A ක ධාරාවක් ගලා යයි නම්, ඒ හරහා ඇති විභව අන්තරය (V = IR) කොපමණද?",
          listOf("$volt V", "${volt + 4} V", "${volt * 2} V", "${volt - 2} V"),
          1,
          "ඕම් නියමය V = IR අනුව: V = $i A × $r Ω = $volt V වේ."
        )
      }
      in 9..16 -> "ප්‍රතිරෝධක ජාල සහ පරිපථ" to run {
        val r1 = 4 + (v % 3) * 2
        val r2 = 6 + ((slot - 9).mod(3)) * 2
        val rTotal = r1 + r2
        Quad(
          "$r1 Ω සහ $r2 Ω ප්‍රතිරෝධක දෙකක් ශ්‍රේණිගතව සම්බන්ධ කළ විට ලැබෙන සමක ප්‍රතිරෝධය (R = R₁ + R₂) කොපමණද?",
          listOf("$rTotal Ω", "${rTotal + 5} Ω", "${r1} Ω", "${r2} Ω"),
          1,
          "ශ්‍රේණිගතව සම්බන්ධ කළ විට සමක ප්‍රතිරෝධය ප්‍රතිරෝධයන්ගේ එකතුවට සමාන වේ (R = $r1 + $r2 = $rTotal Ω)."
        )
      }
      in 17..24 -> "තාපය, උෂ්ණත්වය හා විශිෂ්ට තාප ධාරිතාව" to run {
        val heatList = listOf(
          Quad("සෙල්සියස් අංශක 27 °C කෙල්වින් (K) පරිමාණයට පරිවර්තනය කළ විට ලැබෙන අගය කුමක්ද? (T = θ + 273)", listOf("300 K", "273 K", "246 K", "373 K"), 1, "T = 27 + 273 = 300 K වේ."),
          Quad("ස්කන්ධය 1 kg වූ ද්‍රව්‍යයක උෂ්ණත්වය 1 °C කින් (හෝ 1 K කින්) ඉහළ නැංවීමට අවශ්‍ය තාප ප්‍රමාණය හඳුන්වන්නේ කෙසේද?", listOf("විශිෂ්ට තාප ධාරිතාව (c)", "තාප ධාරිතාව", "විලයනයේ ගුප්ත තාපය", "කැලරි අගය"), 1, "Q = mcΔθ සමීකරණයෙන් c යනු විශිෂ්ට තාප ධාරිතාවයි (ඒකකය: J kg⁻¹ K⁻¹)."),
          Quad("ජලයේ විශිෂ්ට තාප ධාරිතාව ඉතා ඉහළ අගයක් (4200 J kg⁻¹ K⁻¹) ගැනීම නිසා ලැබෙන ප්‍රායෝගික ප්‍රයෝජනය කුමක්ද?", listOf("මෝටර් රථ එන්ජින් සිසිලනකාරකයක් (Coolant) ලෙස භාවිත කිරීම", "ඉක්මනින් රත්වීම", "ඉක්මනින් මිදීම", "ජලයේ ඝනත්වය අඩුවීම"), 1, "ඉහළ විශිෂ්ට තාප ධාරිතාව නිසා විශාල තාප ප්‍රමාණයක් උරාගෙන එන්ජිම සිසිල් කරයි."),
