        val astroList = listOf(
          Quad("සෞරග්‍රහ මණ්ඩලයේ සූර්යයාට ආසන්නතම සහ කුඩාම ග්‍රහලෝකය වන්නේ කුමක්ද?", listOf("බුධ (Mercury)", "සිකුරු", "අඟහරු", "නෙප්චූන්"), 1, "බුධ සූර්යයාට ළඟම පිහිටි ග්‍රහයා වන අතර වායුගෝලයක් නොමැති තරම්ය."),
          Quad("රාත්‍රී අහසේ දීප්තිමත්ව පෙනෙන, ප්‍රමාණයෙන් පෘථිවියට සමාන 'පෘථිවියේ නිවුන් සහෝදරිය' ලෙස හඳුන්වන ග්‍රහයා කුමක්ද?", listOf("සිකුරු (Venus)", "අඟහරු", "බ්‍රහස්පති", "සෙනසුරු"), 1, "සිකුරු ග්‍රහයාගේ ඝන CO₂ වායුගෝලය අධිකව හිරු එළිය පරාවර්තනය කරන බැවින් ඉතා දීප්තිමත්ය."),
          Quad("සෞරග්‍රහ මණ්ඩලයේ විශාලතම ග්‍රහලෝකය වන්නේ කුමක්ද?", listOf("බ්‍රහස්පති (Jupiter)", "සෙනසුරු", "යුරේනස්", "නෙප්චූන්"), 1, "බ්‍රහස්පති යෝධ වායුමය ග්‍රහයෙකු වන අතර එහි ප්‍රකට මහා රතු ලපය (Great Red Spot) ඇත."),
          Quad("පෘථිවිය සහ සූර්යයා අතරට සඳ පැමිණ සඳෙහි සෙවණැල්ල පෘථිවිය මත පතිත වීමෙන් ඇතිවන සංසිද්ධිය කුමක්ද?", listOf("සූර්යග්‍රහණය (Solar Eclipse)", "චන්ද්‍රග්‍රහණය", "වඩදිය-බාදිය", "ධ්‍රැව ප්‍රභාව"), 1, "සූර්යයා, සඳු සහ පෘථිවිය එකම සරල රේඛාවකට පැමිණි විට සූර්යග්‍රහණ ඇතිවේ."),
          Quad("සූර්යයා සහ සඳු අතරට පෘථිවිය පැමිණ පෘථිවියේ සෙවණැල්ලෙන් සඳ වැසී යාමෙන් සිදුවන්නේ කුමක්ද?", listOf("චන්ද්‍රග්‍රහණය (Lunar Eclipse)", "සූර්යග්‍රහණය", "උල්කාපාතය", "සූර්ය සුළි"), 1, "පසළොස්වක පෝය දිනක පෘථිවියේ සෙවණැල්ල තුළට සඳ ඇතුළු වූ විට චන්ද්‍රග්‍රහණය සිදුවේ."),
          Quad("පෘථිවිය තම අක්ෂය වටා භ්‍රමණය වීමට ගතවන කාලය කොපමණද?", listOf("පැය 24 (දින 1)", "දින 365¼", "පැය 12", "දින 30"), 1, "පෘථිවි අක්ෂීය භ්‍රමණය නිසා දිවා-රාත්‍රී ඇතිවන අතර ඒ සඳහා පැය 24 ක් ගතවේ.")
        )
        astroList[(slot - 55 + v).mod(astroList.size)]
      }
    }

    return MockExamQuestion(
      id = qNum,
      questionText = "ආදර්ශ පත්‍රය ${String.format("%02d", paperIdx)} • ප්‍රශ්නය $qNum: ${quad.q}",
      options = quad.opts,
      correctOption = quad.c,
      explanation = quad.exp,
      topicName = topic
    )
  }

  private data class Quad(
    val q: String,
    val opts: List<String>,
    val c: Int,
    val exp: String
  )
}
